test('preferences are opt-in, authenticated, read only and whitelisted without raw record/credential fields',async t=>{const s=await signedPreferences(t);let reads=0;s.api.listBriefPreferences=async(token,ownerId)=>{reads++;assert.equal(token,'FICTIONAL_ACCESS_SECRET');assert.equal(ownerId,owner);return[{id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',version:1,deleted_at:null,...makeBriefPreferencesRecord({palette:'coastal'},owner),payload:{...makeBriefPreferencesRecord({palette:'coastal'},owner).payload,accessToken:'FICTIONAL_PAYLOAD_SECRET'}}];};const result=await call(s.router,'/auth/workspace/preferences',{headers:{cookie:s.cookie}});assert.equal(result.status,200);const data=JSON.parse(result.body);assert.equal(data.preferences.palette,'coastal');assert.equal(data.hasSavedPreferences,true);assert.equal(data.readOnly,true);assert.equal(reads,1);assert.doesNotMatch(result.body,/FICTIONAL_|bbbbbbbb|owner_id|payload|refreshToken/);assert.equal((await call(s.router,'/auth/workspace/preferences',{method:'POST',headers:s.headers})).status,404);});
