async function writeSetup(t,options={}){const s=await setup(t,{allowPreferencesRead:true,allowPreferencesSave:true,...options});s.state.current={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',version:1,deleted_at:null,...makeBriefPreferencesRecord({palette:'coastal',navigation:{order:['school'],hidden:['home']}},owner)};s.state.current.payload.futureField='preserved';s.state.writes=0;s.api.listBriefPreferences=async()=>s.state.current?[structuredClone(s.state.current)]:[];s.api.updateBriefPreferences=async(_token,record,_owner,payload)=>{s.state.writes++;if(!s.state.current||record.version!==s.state.current.version)return[];s.state.current={...s.state.current,version:s.state.current.version+1,payload:structuredClone(payload)};return[structuredClone(s.state.current)];};await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});s.latest=()=>call(s.router,'/auth/workspace/preferences',{headers:{cookie:s.cookie}});s.review=async()=>{const current=JSON.parse((await s.latest()).body);return call(s.router,'/auth/workspace/preferences/review',{method:'POST',headers:s.headers,body:{baseTag:current.baseTag,changes:{palette:'blush',density:'compact',hideAmounts:true}}});};s.save=id=>call(s.router,'/auth/workspace/preferences/save',{method:'POST',headers:s.headers,body:{reviewId:id,approved:true}});return s;}
test('settings review is non-writing and a single approved save preserves unrelated preferences and extension fields',async t=>{const s=await writeSetup(t),review=JSON.parse((await s.review()).body);assert.ok(review.reviewId);assert.equal(s.state.writes,0);const saved=await s.save(review.reviewId);assert.equal(saved.status,200);assert.equal(JSON.parse(saved.body).saved,true);assert.equal(s.state.writes,1);assert.equal(s.state.current.payload.palette,'blush');assert.equal(s.state.current.payload.futureField,'preserved');assert.equal(s.state.current.payload.navigation.order[0],'school');assert.equal((await s.save(review.reviewId)).status,409);assert.equal(s.state.writes,1);assert.doesNotMatch(saved.body,/futureField|bbbbbbbb|FICTIONAL_/);});
test('opt-in section color changes return only display fields and preserve unrelated settings through reviewed save',async t=>{const s=await writeSetup(t,{allowCategoryColorPreferences:true}),current=JSON.parse((await s.latest()).body);assert.deepEqual(Object.keys(current.preferences).sort(),['categoryColors','density','hideAmounts','palette']);const original=structuredClone(s.state.current.payload),changes={palette:current.preferences.palette,density:current.preferences.density,hideAmounts:current.preferences.hideAmounts,categoryColors:{sections:{Work:'warning',School:'positive'},items:{}}};const review=JSON.parse((await call(s.router,'/auth/workspace/preferences/review',{method:'POST',headers:s.headers,body:{baseTag:current.baseTag,changes}})).body);assert.deepEqual(review.changes.map(change=>change.field),['categoryColors']);assert.equal(s.state.writes,0);const saved=await s.save(review.reviewId),body=JSON.parse(saved.body);assert.equal(saved.status,200);assert.deepEqual(body.preferences.categoryColors,changes.categoryColors);assert.equal(Object.keys(body.preferences).sort().join(','),'categoryColors,density,hideAmounts,palette');assert.equal(s.state.current.payload.futureField,original.futureField);assert.deepEqual(s.state.current.payload.navigation,original.navigation);assert.equal(s.state.writes,1);assert.doesNotMatch(saved.body,/bbbbbbbb|futureField|owner_id/);});
test('stale, deleted or expired settings reviews cannot start a write',async t=>{for(const mode of ['changed','deleted','expired']){let clock=1;const s=await writeSetup(t,{now:()=>clock}),review=JSON.parse((await s.review()).body);if(mode==='changed')s.state.current.version++;if(mode==='deleted')s.state.current=null;if(mode==='expired')clock+=300001;assert.equal((await s.save(review.reviewId)).status,409);assert.equal(s.state.writes,0);}});
test('two simultaneous approval requests produce only one settings write',async t=>{const s=await writeSetup(t),review=JSON.parse((await s.review()).body),results=await Promise.all([s.save(review.reviewId),s.save(review.reviewId)]);assert.deepEqual(results.map(row=>row.status).sort(),[200,409]);assert.equal(s.state.writes,1);});
test('lost write acknowledgement consumes the review and cannot silently retry',async t=>{const s=await writeSetup(t),review=JSON.parse((await s.review()).body);s.api.updateBriefPreferences=async()=>{s.state.writes++;throw Error('Fictional lost acknowledgement');};const result=await s.save(review.reviewId);assert.equal(result.status,503);assert.match(result.body,/may have completed/);assert.equal((await s.save(review.reviewId)).status,409);assert.equal(s.state.writes,1);});
test('sign-out during settings save authorization prevents the mutation',async t=>{const s=await writeSetup(t),review=JSON.parse((await s.review()).body);let release;s.api.listBriefPreferences=()=>new Promise(resolve=>release=resolve);const pending=s.save(review.reviewId);while(!release)await new Promise(resolve=>setImmediate(resolve));await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([structuredClone(s.state.current)]);assert.notEqual((await pending).status,200);assert.equal(s.state.writes,0);});
test('wrong acknowledgement content never produces a save success',async t=>{const s=await writeSetup(t),review=JSON.parse((await s.review()).body);s.api.updateBriefPreferences=async()=>{s.state.writes++;return[{...s.state.current,version:2}];};assert.equal((await s.save(review.reviewId)).status,503);assert.equal(s.state.writes,1);});
test('a settings review cannot inject navigation, source permissions or arbitrary record fields',async t=>{const s=await writeSetup(t),baseTag=JSON.parse((await s.latest()).body).baseTag;for(const changes of [{palette:'blush',density:'compact',hideAmounts:true,navigation:{hidden:[]}},{palette:'unknown',density:'compact',hideAmounts:true},{palette:'blush',density:'compact',hideAmounts:'false'}])assert.equal((await call(s.router,'/auth/workspace/preferences/review',{method:'POST',headers:s.headers,body:{baseTag,changes}})).status,409);assert.equal(s.state.writes,0);});
test('saving first default preferences requires review and approval, then returns a verified saved copy',async t=>{const s=await writeSetup(t);s.state.current=null;s.api.addBriefPreferences=async(_token,row)=>{s.state.writes++;s.state.current={...structuredClone(row),id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',version:1,deleted_at:null};return[structuredClone(s.state.current)];};const current=JSON.parse((await s.latest()).body),review=await call(s.router,'/auth/workspace/preferences/review',{method:'POST',headers:s.headers,body:{baseTag:current.baseTag,changes:{palette:current.preferences.palette,density:current.preferences.density,hideAmounts:current.preferences.hideAmounts}}});assert.equal(JSON.parse(review.body).createsPreferences,true);assert.equal(s.state.writes,0);assert.equal((await s.save(JSON.parse(review.body).reviewId)).status,200);assert.equal(s.state.writes,1);});
