async function briefSetup(t){const s=await setup(t,{allowBriefRead:true});await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});s.state.briefRow={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Personal Life',item_type:'note',deleted_at:null,created_at:'2026-11-09T12:00:00Z',payload:{fictional:true,title:'Fictional private title',body:'NEVER_RETURN_THIS_BODY'}};s.api.listPrivateBriefRecords=async(token,ownerId)=>{assert.equal(token,'FICTIONAL_ACCESS_SECRET');assert.equal(ownerId,owner);return[structuredClone(s.state.briefRow)];};return s;}
test('private workspace brief is explicit, authenticated and read only with whitelisted display fields',async t=>{const s=await briefSetup(t),result=await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});assert.equal(result.status,200);const data=JSON.parse(result.body);assert.equal(data.counts.notes,1);assert.equal(data.notes[0].title,'Fictional private title');assert.equal(data.readOnly,true);assert.doesNotMatch(result.body,/NEVER_RETURN|FICTIONAL_ACCESS|bbbbbbbb|owner_id/);assert.equal((await call(s.router,'/auth/workspace/brief',{method:'POST',headers:s.headers})).status,404);const disabled=await setup(t);assert.equal((await call(disabled.router,'/auth/workspace/brief')).status,404);});
test('anonymous and cross-site brief requests cannot start workspace reads',async t=>{const s=await setup(t,{allowBriefRead:true});let reads=0;s.api.listPrivateBriefRecords=async()=>{reads++;return[];};assert.equal((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).status,401);assert.equal((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie,origin:'https://other.test'}})).status,403);assert.equal(reads,0);});
test('logout during a private brief read suppresses late record titles',async t=>{const s=await briefSetup(t);let release;s.api.listPrivateBriefRecords=()=>new Promise(resolve=>release=resolve);const pending=call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});while(!release)await new Promise(resolve=>setImmediate(resolve));await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([s.state.briefRow]);const result=await pending;assert.equal(result.status,503);assert.doesNotMatch(result.body,/Fictional private|NEVER_RETURN/);});
test('foreign brief data and upstream revocation fail closed instead of exposing a partial view',async t=>{for(const mode of ['foreign','revoked']){const s=await briefSetup(t);s.api.listPrivateBriefRecords=async()=>{if(mode==='revoked')s.state.active=false;return[{...s.state.briefRow,...(mode==='foreign'?{owner_id:'cccccccc-cccc-4ccc-8ccc-cccccccccccc'}:{})}];};const result=await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});assert.equal(result.status,503);assert.doesNotMatch(result.body,/Fictional private|NEVER_RETURN|cccccccc/);}});

async function noteSetup(t,options={}){const s=await setup(t,{allowBriefRead:true,allowNoteRead:true,...options});await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});s.row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',version:1,owner_id:owner,household_id:null,visibility:'private',section:'Personal Life',item_type:'note',deleted_at:null,created_at:'2026-11-09T12:00:00Z',payload:{fictional:true,title:'Fictional note',body:'PRIVATE_FICTIONAL_BODY'}};s.reads=0;s.api.listPrivateBriefRecords=async()=>[s.row];s.api.getPrivateNote=async()=>{s.reads++;return[s.row];};s.list=()=>call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});s.open=noteToken=>call(s.router,'/auth/workspace/notes/read',{method:'POST',headers:s.headers,body:{noteToken}});return s;}
test('private note text is default-off and not read until an authenticated selected-note request',async t=>{const off=await setup(t);assert.equal((await call(off.router,'/auth/workspace/notes/read',{method:'POST',headers:off.headers})).status,404);const s=await noteSetup(t),brief=await s.list();assert.equal(s.reads,0);assert.doesNotMatch(brief.body,/PRIVATE_FICTIONAL_BODY/);const token=JSON.parse(brief.body).notes[0].noteToken,result=await s.open(token);assert.equal(result.status,200);assert.equal(JSON.parse(result.body).body,'PRIVATE_FICTIONAL_BODY');assert.equal(s.reads,1);assert.doesNotMatch(result.body,/bbbbbbbb|owner_id|payload/);});
test('selected-note requests require CSRF and reject arbitrary record IDs',async t=>{const s=await noteSetup(t),token=JSON.parse((await s.list()).body).notes[0].noteToken;assert.equal((await call(s.router,'/auth/workspace/notes/read',{method:'POST',headers:{...s.headers,'x-cc-csrf':'invalid'},body:{noteToken:token}})).status,403);assert.equal((await call(s.router,'/auth/workspace/notes/read',{method:'POST',headers:s.headers,body:{noteToken:token,id:s.row.id}})).status,409);assert.equal(s.reads,0);});
test('sign-out or upstream revocation during note retrieval withholds text',async t=>{for(const mode of ['logout','revoked']){const s=await noteSetup(t),token=JSON.parse((await s.list()).body).notes[0].noteToken;let release;s.api.getPrivateNote=()=>new Promise(resolve=>release=resolve);const pending=s.open(token);while(!release)await new Promise(resolve=>setImmediate(resolve));if(mode==='logout')await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});else s.state.active=false;release([s.row]);const result=await pending;assert.equal(result.status,409);assert.doesNotMatch(result.body,/PRIVATE_FICTIONAL_BODY/);}});

test('a fresh brief during final note-session verification suppresses the previous selected note',async t=>{const s=await noteSetup(t),token=JSON.parse((await s.list()).body).notes[0].noteToken;let release,gate=false;const verify=s.api.isSessionActive;s.api.getPrivateNote=async()=>{gate=true;return[s.row];};s.api.isSessionActive=async(...args)=>gate?new Promise(resolve=>release=resolve):verify(...args);const pending=s.open(token);while(!release)await new Promise(resolve=>setImmediate(resolve));gate=false;const refresh=s.list();release(true);await refresh;const result=await pending;assert.equal(result.status,409);assert.doesNotMatch(result.body,/PRIVATE_FICTIONAL_BODY/);});

async function noteEditSetup(t){const s=await noteSetup(t,{allowNoteEdit:true});s.row.payload.extension='preserve';s.writes=0;s.api.getPrivateNoteForEdit=async()=>[structuredClone(s.row)];s.api.updatePrivateNote=async(_token,record,_owner,payload)=>{s.writes++;if(record.version!==s.row.version)return[];s.row={...s.row,version:s.row.version+1,payload:structuredClone(payload)};return[structuredClone(s.row)];};const token=JSON.parse((await s.list()).body).notes[0].noteToken;s.prepare=()=>call(s.router,'/auth/workspace/notes/review',{method:'POST',headers:s.headers,body:{noteToken:token,title:'Edited fictional note',body:'Edited fictional text'}});s.save=reviewId=>call(s.router,'/auth/workspace/notes/save',{method:'POST',headers:s.headers,body:{reviewId,approved:true}});return s;}
