test('note review rejects injected record fields and saving requires request protection',async t=>{const s=await noteEditSetup(t),review=JSON.parse((await s.prepare()).body);assert.equal((await call(s.router,'/auth/workspace/notes/save',{method:'POST',headers:{...s.headers,'x-cc-csrf':'invalid'},body:{reviewId:review.reviewId,approved:true}})).status,403);assert.equal((await call(s.router,'/auth/workspace/notes/review',{method:'POST',headers:s.headers,body:{noteToken:'x'.repeat(43),title:'Fictional',body:'text',owner_id:owner}})).status,409);assert.equal(s.writes,0);});
test('logout during note save preflight prevents writes',async t=>{const s=await noteEditSetup(t),review=JSON.parse((await s.prepare()).body);let release;s.api.getPrivateNoteForEdit=()=>new Promise(resolve=>release=resolve);const pending=s.save(review.reviewId);while(!release)await new Promise(resolve=>setImmediate(resolve));await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([s.row]);assert.equal((await pending).status,409);assert.equal(s.writes,0);});
test('an uncertain note save is not retried and a new brief invalidates old reviews',async t=>{const s=await noteEditSetup(t),review=JSON.parse((await s.prepare()).body);s.api.updatePrivateNote=async()=>{s.writes++;throw Error('Lost acknowledgement');};assert.equal((await s.save(review.reviewId)).status,503);assert.equal((await s.save(review.reviewId)).status,409);assert.equal(s.writes,1);const refreshed=await s.list();assert.equal(refreshed.status,200);assert.equal((await s.save(review.reviewId)).status,409);assert.equal(s.writes,1);});

