async function searchSetup(t,options={}){const s=await setup(t,{allowBriefRead:true,allowSearch:true,...options});s.reads=0;s.row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Personal Life',item_type:'note',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional searchable title',body:'PRIVATE_BODY_NOT_SEARCHABLE'}};s.api.listPrivateBriefRecords=async()=>{s.reads++;return[s.row];};await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});s.search=()=>call(s.router,'/auth/workspace/search',{method:'POST',headers:s.headers,body:{query:'searchable',type:'all',section:'all'}});return s;}
test('private search is opt-in, request protected and title-only with no write routes',async t=>{const off=await setup(t);assert.equal((await call(off.router,'/auth/workspace/search',{method:'POST',headers:off.headers})).status,404);const s=await searchSetup(t),result=await s.search();assert.equal(result.status,200);assert.equal(JSON.parse(result.body).matchCount,1);assert.equal(s.reads,1);assert.doesNotMatch(result.body,/PRIVATE_BODY|bbbbbbbb|owner_id/);assert.equal((await call(s.router,'/auth/workspace/search',{method:'POST',headers:{...s.headers,'x-cc-csrf':'invalid'},body:{query:'title',type:'all',section:'all'}})).status,403);assert.equal(s.reads,1);});
test('malformed search fields cannot start reads and signed-out search is denied',async t=>{const s=await searchSetup(t);assert.equal((await call(s.router,'/auth/workspace/search',{method:'POST',headers:s.headers,body:{query:'',type:'all',section:'all'}})).status,409);assert.equal(s.reads,0);await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});assert.notEqual((await s.search()).status,200);assert.equal(s.reads,0);});
test('sign-out or foreign rows during search suppress all late private titles',async t=>{for(const mode of ['logout','foreign']){const s=await searchSetup(t);let release;s.api.listPrivateBriefRecords=()=>new Promise(resolve=>release=resolve);const pending=s.search();while(!release)await new Promise(resolve=>setImmediate(resolve));if(mode==='logout')await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});else s.row.owner_id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';release([s.row]);const result=await pending;assert.equal(result.status,409);assert.doesNotMatch(result.body,/Fictional searchable|PRIVATE_BODY/);}});

async function openableSearch(t){const s=await searchSetup(t,{allowNoteRead:true,allowNoteEdit:true});s.api.getPrivateNote=async()=>[structuredClone(s.row)];s.api.getPrivateNoteForEdit=async()=>[structuredClone(s.row)];s.api.updatePrivateNote=async(_token,record,_owner,payload)=>{if(record.version!==s.row.version)return[];s.row={...s.row,payload:structuredClone(payload),version:s.row.version+1};return[structuredClone(s.row)];};s.open=noteToken=>call(s.router,'/auth/workspace/notes/read',{method:'POST',headers:s.headers,body:{noteToken}});return s;}
test('search notes have separate read capabilities without invalidating current Brief note handles',async t=>{const s=await openableSearch(t),brief=JSON.parse((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).body),original=brief.notes[0].noteToken,result=await s.search(),token=JSON.parse(result.body).results[0].noteToken;assert.match(token,/^[A-Za-z0-9_-]{43}$/);assert.notEqual(token,original);assert.doesNotMatch(result.body,/PRIVATE_BODY|bbbbbbbb/);assert.equal((await s.open(token)).status,200);assert.equal((await s.open(original)).status,200);});
test('a note opened from search can be reviewed/edited while preserving unrelated fields',async t=>{const s=await openableSearch(t);s.row.payload.extension='preserve';const token=JSON.parse((await s.search()).body).results[0].noteToken;const review=await call(s.router,'/auth/workspace/notes/review',{method:'POST',headers:s.headers,body:{noteToken:token,title:s.row.payload.title,body:'Edited fictional search note'}});assert.equal(review.status,200);assert.equal((await call(s.router,'/auth/workspace/notes/save',{method:'POST',headers:s.headers,body:{reviewId:JSON.parse(review.body).reviewId,approved:true}})).status,200);assert.equal(s.row.payload.extension,'preserve');assert.equal(s.row.payload.body,'Edited fictional search note');assert.equal((await s.open(token)).status,409);});
test('a later search invalidates earlier search handles and withholds pending note text',async t=>{const s=await openableSearch(t),token=JSON.parse((await s.search()).body).results[0].noteToken;let release;s.api.getPrivateNote=()=>new Promise(resolve=>release=resolve);const pending=s.open(token);while(!release)await new Promise(resolve=>setImmediate(resolve));await s.search();release([s.row]);const result=await pending;assert.equal(result.status,409);assert.doesNotMatch(result.body,/PRIVATE_BODY/);});
test('search note handles cannot be used by another browser context even for the same account',async t=>{const s=await openableSearch(t),token=JSON.parse((await s.search()).body).results[0].noteToken,bootstrap=await call(s.router,'/auth/workspace/status'),cookie=bootstrap.headers['Set-Cookie'].split(';')[0],headers={...s.headers,cookie,'x-cc-csrf':JSON.parse(bootstrap.body).csrf};await call(s.router,'/auth/workspace/login',{method:'POST',headers,body:{email:'fictional@example.test',password:'fixture'}});assert.equal((await call(s.router,'/auth/workspace/notes/read',{method:'POST',headers,body:{noteToken:token}})).status,409);});

