test('searched tasks support reviewed editing and fresh completion while preserving subtasks',async t=>{const s=await actionableTaskSearch(t),row=JSON.parse((await s.search()).body).results[0];assert.ok(row.editToken&&row.completionToken);s.token=row.editToken;const edit=JSON.parse((await s.prepare()).body);assert.equal(s.writes,0);assert.equal((await s.save(edit.reviewId)).status,200);assert.equal((await call(s.router,'/auth/workspace/tasks/review',{method:'POST',headers:s.headers,body:{completionToken:row.completionToken}})).status,409);const fresh=JSON.parse((await s.search()).body).results[0],review=await call(s.router,'/auth/workspace/tasks/review',{method:'POST',headers:s.headers,body:{completionToken:fresh.completionToken}});assert.equal(review.status,200);assert.equal((await call(s.router,'/auth/workspace/tasks/complete',{method:'POST',headers:s.headers,body:{reviewId:JSON.parse(review.body).reviewId,approved:true}})).status,200);assert.equal(s.row.payload.done,true);assert.equal(s.row.payload.subtasks[0].done,true);assert.equal(s.row.section,'Work');assert.equal(s.row.payload.day,'2000-01-02');const completed=JSON.parse((await s.search()).body).results[0];assert.equal(completed.completed,true);assert.equal(completed.editToken,undefined);assert.equal(completed.completionToken,undefined);});
test('search does not invalidate existing Brief task edit handles',async t=>{const s=await actionableTaskSearch(t),original=s.token;await s.search();s.token=original;assert.equal((await s.prepare()).status,200);});
test('later searches invalidate older task actions and pending completion reviews',async t=>{const s=await actionableTaskSearch(t),row=JSON.parse((await s.search()).body).results[0];let release;s.api.getPrivateTask=()=>new Promise(resolve=>release=resolve);const pending=call(s.router,'/auth/workspace/tasks/review',{method:'POST',headers:s.headers,body:{completionToken:row.completionToken}});while(!release)await new Promise(resolve=>setImmediate(resolve));await s.search();release([s.row]);assert.equal((await pending).status,409);s.token=row.editToken;assert.equal((await s.prepare()).status,409);assert.equal(s.writes,0);});
