test('appearance-only settings expose two display fields and preserve every other preference on reviewed save',async t=>{const s=await displayOnlySettings(t);delete s.state.current.payload.quietHours;const initial=JSON.parse((await s.latest()).body);assert.deepEqual(Object.keys(initial.preferences).sort(),['density','palette']);assert.doesNotMatch(JSON.stringify(initial),/navigation|quietHours|hideAmounts|futureField/);const original=structuredClone(s.state.current.payload),review=JSON.parse((await s.reviewDisplay()).body);assert.equal(s.state.writes,0);const saved=await s.save(review.reviewId);assert.equal(saved.status,200);assert.deepEqual(Object.keys(JSON.parse(saved.body).preferences).sort(),['density','palette']);assert.equal(s.state.current.payload.hideAmounts,original.hideAmounts);assert.equal(s.state.current.payload.futureField,original.futureField);assert.deepEqual(s.state.current.payload.navigation,original.navigation);assert.deepEqual(s.state.current.payload.sources,original.sources);assert.equal(Object.hasOwn(s.state.current.payload,'quietHours'),false);});
