test('discard during pending appearance review suppresses its late review token',async t=>{const s=await displayOnlySettings(t),baseTag=JSON.parse((await s.latest()).body).baseTag;let release;s.api.listBriefPreferences=()=>new Promise(resolve=>release=resolve);const pending=call(s.router,'/auth/workspace/preferences/review',{method:'POST',headers:s.headers,body:{baseTag,changes:{palette:'blush',density:'compact'}}});while(!release)await new Promise(resolve=>setImmediate(resolve));await call(s.router,'/auth/workspace/preferences/cancel',{method:'POST',headers:s.headers});release([s.state.current]);assert.equal((await pending).status,409);assert.equal(s.state.writes,0);});

