test('fragmented UTF-8 request chunks preserve fictional Unicode login and note text exactly',async t=>{const s=await setup(t);let received;s.api.signIn=async(email,password)=>{received={email,password};return{accessToken:'FICTIONAL',refreshToken:'FICTIONAL_REFRESH',expiresAt:Date.now()+3600000};};const values={email:'fictional@example.test',password:'Fictional-é-学-🔒'},bytes=Buffer.from(JSON.stringify(values));await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,bodyReader:async function*(){for(const byte of bytes)yield Buffer.from([byte]);}});assert.deepEqual(received,values);const n=await noteCreationSetup(t),note={title:'Fictional café 学 🗓',body:'Fictional text — naïve 中文 🔒'},encoded=Buffer.from(JSON.stringify(note)),result=await call(n.router,'/auth/workspace/notes/create-review',{method:'POST',headers:n.headers,bodyReader:async function*(){for(const byte of encoded)yield Buffer.from([byte]);}});assert.equal(result.status,200);assert.equal(JSON.parse(result.body).title,note.title);assert.equal(JSON.parse(result.body).body,note.body);assert.equal(n.writes,0);});
test('new-note review accepts the documented text limit even when JSON escaping exceeds four kilobytes',async t=>{const s=await noteCreationSetup(t),body={title:'Fictional escaped text',body:'\u0001'.repeat(1000)};assert.ok(Buffer.byteLength(JSON.stringify(body))>4096);const reviewed=await call(s.router,'/auth/workspace/notes/create-review',{method:'POST',headers:s.headers,body});assert.equal(reviewed.status,200);assert.equal(JSON.parse(reviewed.body).body,body.body);assert.equal(s.writes,0);});

test('malformed UTF-8 and oversized login requests never reach authentication',async t=>{for(const mode of ['invalid','oversized']){const s=await setup(t),bytes=mode==='invalid'?Buffer.concat([Buffer.from('{"email":"fictional@example.test","password":"'),Buffer.from([0xff]),Buffer.from('"}')]):Buffer.from(JSON.stringify({email:'fictional@example.test',password:'x'.repeat(4096)})),result=await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,bodyReader:async function*(){yield bytes;}});assert.notEqual(result.status,200);assert.equal(s.state.logins,0);assert.doesNotMatch(result.body,/fictional@example|password|\ufffd/);}});

test('selected task route protects context and returns details only after an explicit read',async t=>{const s=await setup(t,{allowBriefRead:true,allowTaskRead:true});const row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Work',item_type:'task',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional selected task',day:'2026-11-09',done:false,description:'Fictional detail',subtasks:[]}};let reads=0;s.api.listPrivateBriefRecords=async()=>[row];s.api.getPrivateTaskDetails=async()=>{reads++;return[row];};const login=JSON.parse((await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}})).body),headers={...s.headers,'x-cc-csrf':login.csrf};const brief=JSON.parse((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).body),token=[...brief.dueTasks,...brief.upcomingTasks][0].taskReadToken;assert.equal(reads,0);assert.doesNotMatch(JSON.stringify(brief),/Fictional detail/);const post=(h,body)=>call(s.router,'/auth/workspace/tasks/read',{method:'POST',headers:h,body});assert.equal((await post({...headers,origin:'https://evil.test'},{taskReadToken:token})).status,403);assert.equal((await post(headers,{taskReadToken:'unknown'})).status,409);assert.equal(reads,0);const result=await post(headers,{taskReadToken:token});assert.equal(result.status,200);assert.equal(JSON.parse(result.body).description,'Fictional detail');assert.doesNotMatch(result.body,/bbbbbbbb|FICTIONAL_ACCESS/);await call(s.router,'/auth/workspace/logout',{method:'POST',headers});assert.notEqual((await post(headers,{taskReadToken:token})).status,200);assert.equal(reads,1);});

test('search paging retires earlier page handles, keeps Brief handles and rejects invalid offsets before reads',async t=>{const s=await setup(t,{allowBriefRead:true,allowSearch:true,allowTaskRead:true}),rows=Array.from({length:51},(_,i)=>({id:'00000000-0000-4000-8000-'+String(i+1).padStart(12,'0'),owner_id:owner,household_id:null,visibility:'private',section:'Work',item_type:'task',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional '+String(i).padStart(3,'0'),day:'2026-11-09',done:false,description:'Fictional details',subtasks:[]}}));let lists=0;s.api.listPrivateBriefRecords=async()=>{lists++;return rows;};s.api.getPrivateTaskDetails=async(_access,id)=>rows.filter(row=>row.id===id);const login=JSON.parse((await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}})).body),headers={...s.headers,'x-cc-csrf':login.csrf};const brief=JSON.parse((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).body),briefToken=brief.dueTasks[0].taskReadToken,fields={query:'',type:'task',section:'all',status:'all'};const post=(path,body)=>call(s.router,'/auth/workspace/'+path,{method:'POST',headers,body});const first=JSON.parse((await post('search',fields)).body),last=JSON.parse((await post('search',{...fields,offset:50})).body);assert.equal(first.results.length,50);assert.equal(last.offset,50);assert.equal(last.results.length,1);assert.equal((await post('tasks/read',{taskReadToken:first.results[0].taskReadToken})).status,409);assert.equal((await post('tasks/read',{taskReadToken:last.results[0].taskReadToken})).status,200);assert.equal((await post('tasks/read',{taskReadToken:briefToken})).status,200);const count=lists;assert.equal((await post('search',{...fields,offset:1})).status,409);assert.equal(lists,count);});

test('event details are suppressed if their selection changes or expires during final session verification',async t=>{for(const mode of ['refresh','expiry']){let stamp=Date.now();const s=await setup(t,{now:()=>stamp,allowBriefRead:true,allowEventCreate:true,allowEventEdit:true,allowEventDetails:true}),row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Calendar',item_type:'event',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional event',day:'2099-12-31',time:'09:30',location:'PRIVATE_FICTIONAL_LOCATION',description:'PRIVATE_FICTIONAL_EVENT_DETAILS'}};s.api.listPrivateBriefRecords=async()=>[structuredClone(row)];await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});const list=()=>call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}}),token=JSON.parse((await list()).body).upcomingEvents[0].eventEditToken;let release,gate=false;const verify=s.api.isSessionActive;s.api.getPrivateEvent=async()=>{gate=true;return[structuredClone(row)];};s.api.isSessionActive=async(...args)=>gate?new Promise(resolve=>release=resolve):verify(...args);const pending=call(s.router,'/auth/workspace/events/edit-read',{method:'POST',headers:s.headers,body:{editToken:token}});for(let attempt=0;!release&&attempt<100;attempt++)await new Promise(resolve=>setImmediate(resolve));if(!release){const early=await pending;assert.fail('Event read ended before verification: '+early.status);}gate=false;const refreshing=mode==='refresh'?list():null;if(mode==='expiry')stamp+=300001;release(true);if(refreshing)await refreshing;const response=await pending;assert.equal(response.status,409);assert.doesNotMatch(response.body,/PRIVATE_FICTIONAL_LOCATION|PRIVATE_FICTIONAL_EVENT_DETAILS/);}});

test('recovery routes are default-off and require explicit sparse APIs',async t=>{const s=await setup(t);assert.equal((await call(s.router,'/auth/workspace/records/deleted',{method:'POST',headers:s.headers})).status,404);assert.throws(()=>createPrivateSessionHttp({origin,api:{},allowRecentlyDeleted:true}));});
test('reviewed removal/restoration uses opaque selections, preserves bodies and requires approval',async t=>{const s=await setup(t,{allowBriefRead:true,allowRecentlyDeleted:true});const row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Personal Life',item_type:'note',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional recovery <script>',body:'Never return this body'}},copy=()=>structuredClone(row);let writes=0;s.api.listPrivateBriefRecords=async()=>row.deleted_at?[]:[copy()];s.api.getPrivateRecordState=async()=>[copy()];s.api.listPrivateDeletedRecords=async()=>row.deleted_at?[copy()]:[];s.api.setPrivateRecordDeletedAt=async(_token,record,_owner,date)=>{assert.equal(record.version,row.version);row.version++;row.deleted_at=date;writes++;return[copy()];};const login=await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fixture',password:'fixture'}});assert.equal(login.status,200);const headers={...s.headers,'x-cc-csrf':JSON.parse(login.body).csrf},post=(path,body={})=>call(s.router,'/auth/workspace/records/'+path,{method:'POST',headers,body});const brief=await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});assert.equal(brief.status,200);const token=JSON.parse(brief.body).notes[0].recordToken;assert.match(token,/^[A-Za-z0-9_-]{43}$/);const review=await post('review',{recordToken:token});assert.equal(review.status,200);assert.doesNotMatch(review.body,/Never return|bbbbbbbb|accessToken/);assert.equal(writes,0);const reviewId=JSON.parse(review.body).reviewId;assert.equal((await post('save',{reviewId,approved:false})).status,409);assert.equal(writes,0);assert.equal((await post('save',{reviewId,approved:true})).status,200);assert.equal(writes,1);assert.equal((await post('save',{reviewId,approved:true})).status,409);const deleted=await post('deleted');assert.equal(deleted.status,200);const record=JSON.parse(deleted.body).records[0];const restore=await post('review',{recordToken:record.recordToken});assert.equal(JSON.parse(restore.body).restoring,true);assert.equal(writes,1);assert.equal((await post('save',{reviewId:JSON.parse(restore.body).reviewId,approved:true})).status,200);assert.equal(writes,2);assert.equal(row.deleted_at,null);assert.equal(row.payload.body,'Never return this body');assert.equal((await post('review',{recordToken:token,recordId:row.id})).status,409);assert.equal((await post('deleted',{offset:1})).status,409);});

test('an in-flight recovery save blocks duplicate writes and Brief refresh until acknowledgement',async t=>{const s=await setup(t,{allowBriefRead:true,allowRecentlyDeleted:true});const row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Personal Life',item_type:'note',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional lock check'}},copy=()=>structuredClone(row);s.api.listPrivateBriefRecords=async()=>row.deleted_at?[]:[copy()];s.api.getPrivateRecordState=async()=>[copy()];let release;s.api.setPrivateRecordDeletedAt=async(_token,_record,_owner,date)=>new Promise(resolve=>{release=()=>{row.deleted_at=date;row.version++;resolve([copy()]);};});const login=await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fixture',password:'fixture'}}),headers={...s.headers,'x-cc-csrf':JSON.parse(login.body).csrf},post=(path,body={})=>call(s.router,'/auth/workspace/records/'+path,{method:'POST',headers,body});const brief=await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}}),review=await post('review',{recordToken:JSON.parse(brief.body).notes[0].recordToken}),reviewId=JSON.parse(review.body).reviewId;const pending=post('save',{reviewId,approved:true});while(!release)await new Promise(resolve=>setImmediate(resolve));assert.equal((await post('save',{reviewId,approved:false})).status,409);assert.equal((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).status,409);release();assert.equal((await pending).status,200);assert.equal(row.version,2);});

test('date browsing is default-off and rejects malformed dates or missing CSRF before record reads',async t=>{const off=await setup(t,{allowBriefRead:true});assert.equal((await call(off.router,'/auth/workspace/brief-date',{method:'POST',headers:off.headers,body:{day:'2026-11-08'}})).status,404);const s=await setup(t,{allowBriefRead:true,allowBriefDates:true,allowTaskCompletion:true});let reads=0;s.api.listPrivateBriefRecords=async()=>{reads++;return[];};const login=await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fixture',password:'fixture'}}),headers={...s.headers,'x-cc-csrf':JSON.parse(login.body).csrf};for(const day of ['2026-02-29',null,['2026-11-09'],'2101-01-01'])assert.equal((await call(s.router,'/auth/workspace/brief-date',{method:'POST',headers,body:{day}})).status,409);assert.equal((await call(s.router,'/auth/workspace/brief-date',{method:'POST',headers:{...headers,'x-cc-csrf':'invalid'},body:{day:'2026-11-08'}})).status,403);assert.equal(reads,0);const result=await call(s.router,'/auth/workspace/brief-date',{method:'POST',headers,body:{day:'2026-11-08'}});assert.equal(result.status,200);assert.equal(JSON.parse(result.body).day,'2026-11-08');assert.equal(JSON.parse(result.body).selectedDate,true);assert.equal(reads,1);});

