 test('Calendar pause requires authenticated protected requests and binds to the signed-in owner',async t=>{let pauses=[];const io={mode:'on-open',maxEvents:250,selectionForOwner:async()=>{throw Error('No reads expected');},readCalendarWindow:async()=>{throw Error('No native reads expected');},pause:async id=>{pauses.push(id);return{paused:true};}},s=await setup(t,{macCalendarOpenPreviewIO:io});const path='/auth/workspace/calendar-source/pause';assert.equal((await call(s.router,path,{method:'POST',headers:s.headers})).status,401);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});for(const headers of [{...s.headers,origin:'https://foreign.test'},{...s.headers,'x-cc-csrf':'invalid'}])assert.equal((await call(s.router,path,{method:'POST',headers})).status,403);assert.equal((await call(s.router,path,{method:'POST',headers:s.headers,body:{ownerId:'foreign'}})).status,409);assert.deepEqual(pauses,[]);assert.equal((await call(s.router,path,{method:'POST',headers:s.headers})).status,200);assert.deepEqual(pauses,[owner]);});

test('date-only task review and save preserve description, priority, checklist and unknown extension fields',async t=>{const s=await taskEditSetup(t);Object.assign(s.row.payload,{description:'Fictional long description',priority:'High',fixtureExtension:{keep:true}});const original=structuredClone(s.row.payload);const reviewed=await call(s.router,'/auth/workspace/tasks/edit-review',{method:'POST',headers:s.headers,body:{editToken:s.token,title:s.row.payload.title,day:'2000-01-03',section:s.row.section}});assert.equal(reviewed.status,200);assert.equal(s.writes,0);assert.doesNotMatch(reviewed.body,/Fictional long description|fixtureExtension/);const id=JSON.parse(reviewed.body).reviewId;const saved=await Promise.all([s.save(id),s.save(id)]);assert.deepEqual(saved.map(r=>r.status).sort(),[200,409]);assert.equal(s.writes,1);assert.deepEqual({...s.row.payload,day:original.day},original);});

