test('saved-mail route requires explicit scope, sign-in, empty body and CSRF before metadata reads',async t=>{const off=await setup(t);assert.equal((await call(off.router,'/auth/workspace/saved-mail',{method:'POST',headers:off.headers})).status,404);const s=await setup(t,{allowBriefRead:true,allowSavedMailRead:true});let reads=0;s.api.listSavedMailMetadata=async(_token,id)=>{assert.equal(id,owner);reads++;return[savedMailRow()];};const path='/auth/workspace/saved-mail';assert.equal((await call(s.router,path,{method:'POST',headers:s.headers})).status,401);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});assert.equal((await call(s.router,path,{method:'POST',headers:{...s.headers,'x-cc-csrf':'bad'}})).status,403);assert.equal((await call(s.router,path,{method:'POST',headers:s.headers,body:{ownerId:owner}})).status,409);assert.equal(reads,0);const result=await call(s.router,path,{method:'POST',headers:s.headers});assert.equal(result.status,200);assert.equal(reads,1);assert.equal(JSON.parse(result.body).records[0].subject,'Fictional mail subject');assert.doesNotMatch(result.body,/bbbbbbbb|owner_id|accessToken|refreshToken/);});
test('saved-mail foreign metadata and late signed-out responses are withheld completely',async t=>{for(const mode of ['foreign','logout']){const s=await setup(t,{allowBriefRead:true,allowSavedMailRead:true});await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});let release;s.api.listSavedMailMetadata=()=>new Promise(r=>release=r);const pending=call(s.router,'/auth/workspace/saved-mail',{method:'POST',headers:s.headers});while(!release)await new Promise(r=>setImmediate(r));const row=savedMailRow();if(mode==='foreign')row.owner_id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';else await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([row]);const result=await pending;assert.notEqual(result.status,200);assert.doesNotMatch(result.body,/Fictional mail subject|Fictional sender/);}});
test('saved-mail pages accept only bounded five-step offsets before issuing sparse reads',async t=>{const s=await setup(t,{allowBriefRead:true,allowSavedMailRead:true});let reads=0,seenOffset;s.api.listSavedMailMetadata=async(_token,id,options)=>{assert.equal(id,owner);reads++;seenOffset=options.offset;return[savedMailRow()];};await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});for(const offset of [-5,1,500,null,'5'])assert.equal((await call(s.router,'/auth/workspace/saved-mail',{method:'POST',headers:s.headers,body:{offset}})).status,409);assert.equal(reads,0);const result=await call(s.router,'/auth/workspace/saved-mail',{method:'POST',headers:s.headers,body:{offset:5}});assert.equal(result.status,200);assert.equal(seenOffset,5);assert.equal(JSON.parse(result.body).offset,5);});

test('saved accounts require explicit scope, active sign-in, CSRF and empty input, and suppress a signed-out late response',async t=>{const off=await setup(t),path='/auth/workspace/saved-finance-accounts';assert.equal((await call(off.router,path,{method:'POST',headers:off.headers})).status,404);let reads=0,release;const s=await setup(t,{allowBriefRead:true,allowSavedFinanceRead:true,savedFinanceReader:async actor=>{reads++;assert.equal(actor.ownerId,owner);return new Promise(r=>release=r);}});assert.equal((await call(s.router,path,{method:'POST',headers:s.headers})).status,401);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});assert.equal((await call(s.router,path,{method:'POST',headers:{...s.headers,'x-cc-csrf':'bad'}})).status,403);assert.equal((await call(s.router,path,{method:'POST',headers:s.headers,body:{ownerId:owner}})).status,409);assert.equal(reads,0);const pending=call(s.router,path,{method:'POST',headers:s.headers});while(!release)await new Promise(r=>setImmediate(r));await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([savedAccountRow()]);const result=await pending;assert.notEqual(result.status,200);assert.doesNotMatch(result.body,/Fictional checking|123456|ACCOUNT_ID/);});

test('saved transactions require their own scope and bounded input before a reader can run',async t=>{let reads=0;const s=await setup(t,{allowBriefRead:true,allowSavedFinanceRead:true,savedFinanceReader:async()=>[],allowSavedTransactionsRead:true,savedTransactionReader:async(actor,{offset})=>{reads++;assert.equal(actor.ownerId,owner);assert.equal(offset,20);return[];}}),path='/auth/workspace/saved-finance-transactions';assert.equal((await call(s.router,path,{method:'POST',headers:s.headers})).status,401);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});for(const body of [{ownerId:owner},{offset:1},{offset:null},{offset:500}])assert.equal((await call(s.router,path,{method:'POST',headers:s.headers,body})).status,409);assert.equal((await call(s.router,path,{method:'POST',headers:{...s.headers,'x-cc-csrf':'bad'},body:{offset:20}})).status,403);assert.equal(reads,0);const result=await call(s.router,path,{method:'POST',headers:s.headers,body:{offset:20}});assert.equal(result.status,200);assert.equal(JSON.parse(result.body).offset,20);assert.equal(reads,1);});

async function projectSetup(t,options={}){const s=await setup(t,{allowProjects:true,...options});s.writes=0;s.row=null;s.api.listPrivateProjects=async()=>s.row&&s.row.deleted_at===null?[structuredClone(s.row)]:[];s.api.getPrivateProject=async()=>s.row&&s.row.deleted_at===null?[structuredClone(s.row)]:[];s.api.addPrivateProject=async(_token,r)=>{s.writes++;s.row={...structuredClone(r),version:1,deleted_at:null,created_at:new Date().toISOString(),updated_at:new Date().toISOString()};return[structuredClone(s.row)];};s.api.updatePrivateProject=async(_token,r,_owner,p)=>{s.writes++;if(s.row.version!==r.version)return[];s.row={...s.row,payload:p.payload,section:p.section,version:r.version+1};return[structuredClone(s.row)];};await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});s.project=(action,body={})=>call(s.router,'/auth/workspace/projects/'+action,{method:'POST',headers:s.headers,body});s.fields={title:'Fictional project',description:'PRIVATE_PROJECT_BODY',section:'Work',status:'Active'};await s.project('list');return s;}
test('private project HTTP is opt-in, protected, reviewed and consumes approval once',async t=>{const off=await setup(t);assert.equal((await call(off.router,'/auth/workspace/projects/list',{method:'POST',headers:off.headers})).status,404);const s=await projectSetup(t);for(const headers of [{...s.headers,origin:'https://other.test'},{...s.headers,'x-cc-csrf':'wrong'}])assert.equal((await call(s.router,'/auth/workspace/projects/review',{method:'POST',headers,body:{action:'create',fields:s.fields}})).status,403);assert.equal((await s.project('review',{action:'create',fields:s.fields,owner_id:owner})).status,409);const review=await s.project('review',{action:'create',fields:s.fields});assert.equal(review.status,200);assert.equal(s.writes,0);const id=JSON.parse(review.body).reviewId;assert.equal((await s.project('save',{reviewId:id,approved:false})).status,409);const results=await Promise.all([s.project('save',{reviewId:id,approved:true}),s.project('save',{reviewId:id,approved:true})]);assert.deepEqual(results.map(r=>r.status).sort(),[200,409]);assert.equal(s.writes,1);const list=await s.project('list');assert.doesNotMatch(list.body,/PRIVATE_PROJECT_BODY|owner_id/);const read=await s.project('read',{projectToken:JSON.parse(list.body).projects[0].projectToken});assert.equal(JSON.parse(read.body).description,'PRIVATE_PROJECT_BODY');});
test('project HTTP withholds late details after logout',async t=>{const s=await projectSetup(t);let r=JSON.parse((await s.project('review',{action:'create',fields:s.fields})).body);await s.project('save',{reviewId:r.reviewId,approved:true});const list=JSON.parse((await s.project('list')).body);let release;s.api.getPrivateProject=()=>new Promise(resolve=>release=resolve);const pending=s.project('read',{projectToken:list.projects[0].projectToken});while(!release)await new Promise(resolve=>setImmediate(resolve));await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([s.row]);const result=await pending;assert.equal(result.status,409);assert.doesNotMatch(result.body,/PRIVATE_PROJECT_BODY/);});
test('cancelling projects during final session verification suppresses an older project review',async t=>{const s=await projectSetup(t);let release,gate=true;const verify=s.api.isSessionActive;let calls=0;s.api.isSessionActive=async(...args)=>{calls++;if(gate&&calls===2)return new Promise(resolve=>release=resolve);return verify(...args);};const pending=s.project('review',{action:'create',fields:s.fields});while(!release)await new Promise(resolve=>setImmediate(resolve));gate=false;assert.equal((await s.project('cancel')).status,200);release(true);const result=await pending;assert.equal(result.status,409);assert.doesNotMatch(result.body,/PRIVATE_PROJECT_BODY|reviewId/);assert.equal(s.writes,0);});

test('project review accepts the full supported description length through bounded HTTP input',async t=>{const s=await projectSetup(t),description='漢字\n'.repeat(3333)+'x';assert.equal(description.length,10000);const result=await s.project('review',{action:'create',fields:{...s.fields,description}});assert.equal(result.status,200);assert.equal(JSON.parse(result.body).description,description);assert.equal(s.writes,0);const oversized=await s.project('review',{action:'create',fields:{...s.fields,description:'x'.repeat(70000)}});assert.equal(oversized.status,409);assert.equal(s.writes,0);});
test('membership HTTP is separately scoped, selected-token-only and approval-bound without exposing task details',async t=>{const off=await projectSetup(t);assert.equal((await off.project('tasks-list')).status,404);const s=await projectSetup(t,{allowProjectTaskLinks:true}),created=JSON.parse((await s.project('review',{action:'create',fields:s.fields})).body);await s.project('save',{reviewId:created.reviewId,approved:true});const projectToken=JSON.parse((await s.project('list')).body).projects[0].projectToken,task={id:'dddddddd-dddd-4ddd-8ddd-dddddddddddd',owner_id:owner,household_id:null,visibility:'private',section:'Home',item_type:'task',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional linked task',done:false}},stamp=new Date().toISOString();let writes=0,link=null;s.api.listProjectTaskChoices=async()=>[structuredClone(task)];s.api.getProjectTaskChoice=async()=>[structuredClone(task)];s.api.getProjectLinkTarget=async()=>[structuredClone(s.row)];s.api.listProjectTaskMemberships=async()=>link?[structuredClone(link)]:[];s.api.getTaskProjectMembership=async()=>link?[structuredClone(link)]:[];s.api.setTaskProjectLink=async(_token,v)=>{writes++;assert.equal(v.taskVersion,1);task.version++;link={id:'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',owner_id:owner,household_id:null,visibility:'private',section:'Personal Life',item_type:'project_task_link',origin:'PRIVATE_COOKIE_PROJECT_TASK_LINK',version:1,deleted_at:null,created_at:stamp,updated_at:stamp,payload:{fictional:true,schemaVersion:1,taskId:task.id,projectId:s.row.id}};return{taskId:task.id,taskVersion:task.version,linkRecord:structuredClone(link)};};assert.equal((await s.project('tasks-list',{projectToken,taskId:task.id})).status,409);const list=await s.project('tasks-list',{projectToken});assert.equal(list.status,200);assert.doesNotMatch(list.body,/PRIVATE_PROJECT_BODY|owner_id|dddddddd/);const taskToken=JSON.parse(list.body).tasks[0].taskToken;const review=await s.project('tasks-review',{taskToken,linked:true});assert.equal(review.status,200);assert.equal(writes,0);const id=JSON.parse(review.body).reviewId;assert.equal((await s.project('tasks-save',{reviewId:id,approved:false})).status,409);const results=await Promise.all([s.project('tasks-save',{reviewId:id,approved:true}),s.project('tasks-save',{reviewId:id,approved:true})]);assert.deepEqual(results.map(r=>r.status).sort(),[200,409]);assert.equal(writes,1);});

async function recoverableProject(t){
 const s=await projectSetup(t,{allowBriefRead:true,allowRecentlyDeleted:true});
 s.api.getPrivateRecordState=async(_token,id,who)=>s.row?.id===id&&who===owner?[structuredClone(s.row)]:[];
 s.api.listPrivateDeletedRecords=async()=>s.row?.deleted_at?[structuredClone(s.row)]:[];
 s.api.setPrivateRecordDeletedAt=async(_token,record,who,date)=>{s.writes++;if(who!==owner||s.row.version!==record.version||s.row.deleted_at!==record.deleted_at)return[];s.row.deleted_at=date;s.row.version++;return[structuredClone(s.row)];};
 const review=JSON.parse((await s.project('review',{action:'create',fields:s.fields})).body);await s.project('save',{reviewId:review.reviewId,approved:true});
 s.recovery=(action,body={})=>call(s.router,'/auth/workspace/records/'+action,{method:'POST',headers:s.headers,body});
 return s;
}
test('project removal and restoration use sparse displayed handles, explicit approval and preserved contents',async t=>{
 const s=await recoverableProject(t),payload=structuredClone(s.row.payload),list=JSON.parse((await s.project('list')).body),key=list.projects[0].recordToken;
 assert.match(key,/^[A-Za-z0-9_-]{43}$/);assert.doesNotMatch(JSON.stringify(list),/PRIVATE_PROJECT_BODY|owner_id|schemaVersion/);
 const reviewed=await s.recovery('review',{recordToken:key});assert.equal(reviewed.status,200);const review=JSON.parse(reviewed.body);assert.equal(review.type,'project');assert.equal(s.writes,1);
 assert.equal((await s.recovery('save',{reviewId:review.reviewId,approved:false})).status,409);assert.equal(s.writes,1);
 assert.equal((await s.recovery('save',{reviewId:review.reviewId,approved:true})).status,200);assert.equal(s.writes,2);assert.deepEqual(s.row.payload,payload);assert.equal(JSON.parse((await s.project('list')).body).matchCount,0);
 assert.equal((await s.recovery('save',{reviewId:review.reviewId,approved:true})).status,409);assert.equal(s.writes,2);
 const removed=JSON.parse((await s.recovery('deleted')).body);assert.equal(removed.records[0].type,'project');const restore=JSON.parse((await s.recovery('review',{recordToken:removed.records[0].recordToken})).body);
 assert.equal(restore.restoring,true);assert.equal((await s.recovery('save',{reviewId:restore.reviewId,approved:true})).status,200);assert.equal(s.row.deleted_at,null);assert.deepEqual(s.row.payload,payload);assert.equal(JSON.parse((await s.project('list')).body).matchCount,1);
});
test('project recovery handles expire on new listing/cancel and stale edits cannot remove',async t=>{
 for(const mode of ['list','cancel','edit']){const s=await recoverableProject(t),list=JSON.parse((await s.project('list')).body),key=list.projects[0].recordToken;
  if(mode==='list')await s.project('list');if(mode==='cancel')await s.project('cancel');if(mode==='edit')s.row.version++;
  assert.equal((await s.recovery('review',{recordToken:key})).status,409);assert.equal(s.writes,1);assert.equal(s.row.deleted_at,null);
 }
 const off=await projectSetup(t);const review=JSON.parse((await off.project('review',{action:'create',fields:off.fields})).body);await off.project('save',{reviewId:review.reviewId,approved:true});assert.equal(JSON.parse((await off.project('list')).body).projects[0].recordToken,undefined);
});
test('a linked-project database refusal keeps its contents and consumes the uncertain approval without retry',async t=>{
 const s=await recoverableProject(t),list=JSON.parse((await s.project('list')).body),review=JSON.parse((await s.recovery('review',{recordToken:list.projects[0].recordToken})).body),before=structuredClone(s.row);let attempts=0;
 s.api.setPrivateRecordDeletedAt=async()=>{attempts++;throw Error('Unlink tasks before removing a project.');};
 const result=await s.recovery('save',{reviewId:review.reviewId,approved:true});assert.equal(result.status,503);assert.equal((await s.recovery('save',{reviewId:review.reviewId,approved:true})).status,409);assert.equal(attempts,1);assert.deepEqual(s.row,before);
});

