ows[0],request=(path,body)=>call(s.router,'/auth/workspace/'+path,{method:'POST',headers:s.headers,body});const pending=await request('tasks/review',{completionToken:task.completionToken});assert.equal(pending.status,200);const reviewId=JSON.parse(pending.body).reviewId;const calendar=await request('calendar',{query:'',type:'event',section:'all',status:'all',dateFrom:day,dateTo:day});assert.equal(calendar.status,200);const taskRead=await request('tasks/read',{taskReadToken:task.taskReadToken}),noteRead=await request('notes/read',{noteToken:note.noteToken}),eventRead=await request('events/edit-read',{editToken:event.eventEditToken});for(const result of [taskRead,noteRead,eventRead]){assert.equal(result.status,200);assert.ok(JSON.parse(result.body).expiresAt<=brief.widgetSourceExpiresAt);}assert.equal(JSON.parse(noteRead.body).body,'Exact original note body');assert.equal(JSON.parse(eventRead.body).title,'Fictional coexist event');assert.equal(writes,0);assert.equal((await request('tasks/complete',{reviewId,approved:true})).status,200);assert.equal(writes,1);assert.equal(rows[0].payload.done,true);
