test('private list-template routes are default-off and require optional-date reviewed checklist creation',async t=>{const off=await setup(t);assert.equal((await call(off.router,'/auth/workspace/tasks/templates-list',{method:'POST',headers:off.headers})).status,404);assert.throws(()=>createPrivateSessionHttp({origin,api:{},allowListTemplates:true}),/Protected list templates/);const s=await setup(t,{allowBriefRead:true,allowTaskCreate:true,allowTaskSubtasks:true,allowTaskRead:true,allowTaskDescriptionEdit:true,allowTaskEdit:true,allowTaskCompletion:true,allowTaskReopen:true,allowSearch:true,allowUndatedTasks:true,allowListTemplates:true});await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});const post=(name,body)=>call(s.router,'/auth/workspace/tasks/templates-'+name,{method:'POST',headers:s.headers,body});assert.equal((await post('list',{})).status,200);const created=await post('review',{action:'create',fields:{name:'Weekly reset',taskTitle:'Reset the week',checklist:['Review calendar','Plan meals']}});assert.equal(created.status,200,created.body);assert.equal(s.state.templateWrites,0);const saved=await post('save',{reviewId:JSON.parse(created.body).reviewId,approved:true});assert.equal(saved.status,200);assert.equal(s.state.templateWrites,1);const list=await post('list',{});assert.equal(list.status,200);const token=JSON.parse(list.body).templates[0].selectionToken,detail=await post('read',{selectionToken:token});assert.equal(detail.status,200);assert.deepEqual(JSON.parse(detail.body).checklist,['Review calendar','Plan meals']);const draft=await post('instantiate',{selectionToken:token});assert.equal(draft.status,200);const taskDraft=JSON.parse(draft.body).taskDraft;assert.deepEqual(taskDraft,{title:'Reset the week',day:'',section:'Personal Life',subtasks:['Review calendar','Plan meals']});s.api.addFictionalTask=async(_token,row)=>{s.state.taskWrites++;s.state.createdTask={...structuredClone(row),version:1,created_at:'2026-11-21T12:00:00.000Z',updated_at:'2026-11-21T12:00:00.000Z',deleted_at:null};return[structuredClone(s.state.createdTask)];};s.api.getPrivateTask=async(_token,id,who)=>s.state.createdTask?.id===id&&s.state.createdTask.owner_id===who?[structuredClone(s.state.createdTask)]:[];const taskReview=await call(s.router,'/auth/workspace/tasks/create-review',{method:'POST',headers:s.headers,body:taskDraft});assert.equal(taskReview.status,200);assert.equal(s.state.taskWrites,0);const taskSaved=await call(s.router,'/auth/workspace/tasks/create-save',{method:'POST',headers:s.headers,body:{reviewId:JSON.parse(taskReview.body).reviewId,approved:true}});assert.equal(taskSaved.status,200);assert.equal(s.state.taskWrites,1);assert.equal(new Set(s.state.createdTask.payload.subtasks.map(step=>step.id)).size,2);assert.ok(s.state.createdTask.payload.subtasks.every(step=>step.done===false));assert.equal(s.state.templateWrites,1);assert.equal(s.state.templates.length,1);});

test('Home cleaning task creation is separately scoped, reviewed and carries forward without changing its date',async t=>{const s=await creationSetup(t,{allowTaskDescriptions:true,allowTaskSubtasks:true,allowTaskRead:true,allowTaskEdit:true,allowTaskDescriptionEdit:true,allowTaskCompletion:true,allowHomeCleaning:true});const fields={title:'Clean kitchen',day:'2026-11-09',section:'Home',description:'',subtasks:['Wipe counters'],homeCleaning:{room:'Kitchen',assignee:'Sam',rollover:true}};const review=await call(s.router,'/auth/workspace/tasks/create-review',{method:'POST',headers:s.headers,body:fields});assert.equal(review.status,200,review.body);assert.equal(s.writes,0);assert.deepEqual(JSON.parse(review.body).homeCleaning,fields.homeCleaning);const saved=await call(s.router,'/auth/workspace/tasks/create-save',{method:'POST',headers:s.headers,body:{reviewId:JSON.parse(review.body).reviewId,approved:true}});assert.equal(saved.status,200);assert.equal(s.writes,1);assert.deepEqual(s.row.payload.homeCleaning,fields.homeCleaning);assert.equal(s.row.payload.day,fields.day);assert.equal(s.row.payload.subtasks[0].done,false);});

test('Home cleaning edits are selected, reviewed and one-use through the protected task route',async t=>{const s=await taskEditSetup(t,{allowTaskCreate:true,allowTaskRead:true,allowTaskDescriptionEdit:true,allowTaskDescriptions:true,allowTaskSubtasks:true,allowTaskCompletion:true,allowHomeCleaning:true});s.row.payload.homeCleaning={room:'Kitchen',assignee:'Sam',rollover:true};const result=await call(s.router,'/auth/workspace/tasks/edit-review',{method:'POST',headers:s.headers,body:{editToken:s.token,title:s.row.payload.title,day:s.row.payload.day,section:'Home',homeCleaning:{room:'Kitchen',assignee:'Sam',rollover:false}}});assert.equal(result.status,200,result.body);assert.equal(s.writes,0);assert.deepEqual(JSON.parse(result.body).homeCleaning,{room:'Kitchen',assignee:'Sam',rollover:false});const reviewId=JSON.parse(result.body).reviewId;assert.equal((await s.save(reviewId)).status,200);assert.equal(s.writes,1);assert.equal(s.row.payload.day,'2000-01-01');assert.deepEqual(s.row.payload.homeCleaning,{room:'Kitchen',assignee:'Sam',rollover:false});assert.equal((await s.save(reviewId)).status,409);});

test('Home grocery items use reviewed optional-date creation and exact private quantity/favorite metadata',async t=>{const scopes={allowTaskDescriptions:true,allowTaskSubtasks:true,allowTaskRead:true,allowTaskEdit:true,allowTaskDescriptionEdit:true,allowTaskCompletion:true,allowTaskReopen:true,allowSearch:true,allowUndatedTasks:true,allowHomeGroceries:true},s=await creationSetup(t,scopes),fields={title:'Oat milk',day:'',section:'Home',description:'',subtasks:[],homeGrocery:{quantity:'2 cartons',favorite:true}};const review=await call(s.router,'/auth/workspace/tasks/create-review',{method:'POST',headers:s.headers,body:fields});assert.equal(review.status,200,review.body);assert.equal(s.writes,0);assert.deepEqual(JSON.parse(review.body).homeGrocery,fields.homeGrocery);const saved=await call(s.router,'/auth/workspace/tasks/create-save',{method:'POST',headers:s.headers,body:{reviewId:JSON.parse(review.body).reviewId,approved:true}});assert.equal(saved.status,200);assert.deepEqual(s.row.payload.homeGrocery,fields.homeGrocery);assert.equal(s.row.payload.day,null);});
test('Home grocery edits use selected review and preserve optional dates',async t=>{const scopes={allowTaskCreate:true,allowTaskRead:true,allowTaskDescriptionEdit:true,allowTaskDescriptions:true,allowTaskSubtasks:true,allowTaskCompletion:true,allowTaskReopen:true,allowSearch:true,allowUndatedTasks:true,allowHomeGroceries:true},s=await taskEditSetup(t,scopes);s.row.payload.day=null;s.row.payload.homeGrocery={quantity:'1 bag',favorite:false};s.api.listPrivateBriefRecords=async()=>[structuredClone(s.row)];s.token=JSON.parse((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).body).undatedTasks[0].editToken;const result=await call(s.router,'/auth/workspace/tasks/edit-review',{method:'POST',headers:s.headers,body:{editToken:s.token,title:s.row.payload.title,day:'',section:'Home',homeGrocery:{quantity:'2 bags',favorite:true}}});assert.equal(result.status,200,result.body);assert.equal(s.writes,0);assert.deepEqual(JSON.parse(result.body).homeGrocery,{quantity:'2 bags',favorite:true});assert.equal((await s.save(JSON.parse(result.body).reviewId)).status,200);assert.deepEqual(s.row.payload.homeGrocery,{quantity:'2 bags',favorite:true});assert.equal(s.row.payload.day,null);});

test('Home grocery list templates are separately gated by the reviewed grocery scope',async t=>{const scopes={allowBriefRead:true,allowTaskCreate:true,allowTaskSubtasks:true,allowTaskRead:true,allowTaskDescriptionEdit:true,allowTaskDescriptions:true,allowTaskEdit:true,allowTaskCompletion:true,allowTaskReopen:true,allowSearch:true,allowUndatedTasks:true,allowHomeGroceries:true,allowListTemplates:true},s=await setup(t,scopes);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});const post=(name,body)=>call(s.router,'/auth/workspace/tasks/templates-'+name,{method:'POST',headers:s.headers,body});assert.equal((await post('list',{})).status,200);const created=await post('review',{action:'create',section:'Home',fields:{name:'Weekly shop',taskTitle:'Buy groceries',checklist:['Oats','Milk']}});assert.equal(created.status,200,created.body);const saved=await post('save',{reviewId:JSON.parse(created.body).reviewId,approved:true});assert.equal(saved.status,200,saved.body);const view=JSON.parse((await post('list',{})).body);assert.equal(view.templates[0].section,'Home');const token=view.templates[0].selectionToken,draft=await post('instantiate',{selectionToken:token});assert.deepEqual(JSON.parse(draft.body).taskDraft,{title:'Buy groceries',day:'',section:'Home',subtasks:['Oats','Milk']});const blocked=await setup(t,{allowBriefRead:true,allowTaskCreate:true,allowTaskSubtasks:true,allowTaskRead:true,allowTaskDescriptionEdit:true,allowTaskEdit:true,allowTaskCompletion:true,allowTaskReopen:true,allowSearch:true,allowUndatedTasks:true,allowListTemplates:true});await call(blocked.router,'/auth/workspace/login',{method:'POST',headers:blocked.headers,body:{email:'fictional@example.test',password:'fixture'}});const blockedReview=await call(blocked.router,'/auth/workspace/tasks/templates-review',{method:'POST',headers:blocked.headers,body:{action:'create',section:'Home',fields:{name:'Nope',taskTitle:'Nope',checklist:[]}}});assert.equal(blockedReview.status,409);});

test('Home delivery tracking is default-off and saves only through the scoped task review route',async t=>{const base={allowTaskCreate:true,allowTaskDescriptions:true,allowTaskRead:true,allowTaskEdit:true,allowTaskDescriptionEdit:true,allowTaskCompletion:true},off=await creationSetup(t,base);const denied=await call(off.router,'/auth/workspace/tasks/create-review',{method:'POST',headers:off.headers,body:{title:'Package',day:'2026-11-24',section:'Home',homeDelivery:{status:'ordered',orderDay:'2026-11-20',expectedDay:'2026-11-24',returnByDay:'',carrier:'UPS',trackingReference:'123',refundNote:''}}});assert.equal(denied.status,409);const s=await creationSetup(t,{...base,allowHomeDeliveries:true});const homeDelivery={status:'ordered',orderDay:'2026-11-20',expectedDay:'2026-11-24',returnByDay:'',carrier:'UPS',trackingReference:'123',refundNote:''},fields={title:'Package arrival',day:'2026-11-24',section:'Home',homeDelivery};const review=await call(s.router,'/auth/workspace/tasks/create-review',{method:'POST',headers:s.headers,body:fields});assert.equal(review.status,200,review.body);assert.equal(s.writes,0);assert.deepEqual(JSON.parse(review.body).homeDelivery,homeDelivery);const saved=await call(s.router,'/auth/workspace/tasks/create-save',{method:'POST',headers:s.headers,body:{reviewId:JSON.parse(review.body).reviewId,approved:true}});assert.equal(saved.status,200,saved.body);assert.deepEqual(s.row.payload.homeDelivery,homeDelivery);});
